function ageHours(row) {
  const t = Date.parse(row.at);
  return isNaN(t) ? 0 : (Date.now() - t) / 3600000;
}

function daysBetween(a, b) {
  const x = Date.parse(a + 'T00:00:00Z');
  const y = Date.parse(b + 'T00:00:00Z');
  if (isNaN(x) || isNaN(y)) return Infinity;
  return Math.round(Math.abs(y - x) / 86400000);
}

// Everything that actually went out, newest first.
function postedHistory(rows) {
  return rows.filter((r) => r.status === 'posted')
    .map((r) => ({ date: r.date, slug: r.slug, slot: r.slot, pillar: r.pillar, hook: r.hook, urn: r.urn, at: r.at }))
    .sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : 0));
}

function recentHooks(history, today, days) {
  return history.filter((h) => h.hook && daysBetween(h.date, today) <= days)
    .map((h) => ({ hook: h.hook, slug: h.slug, date: h.date }));
}

// Local calendar date, weekday and hour in the configured timezone. Intl rather than
// toISOString: a job at 08:00 Singapore is still "yesterday" in UTC.
function localParts(date, tz) {
  const f = new Intl.DateTimeFormat('en-GB', {
    timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'short',
    hour: '2-digit', hourCycle: 'h23'
  });
  const p = {};
  for (const part of f.formatToParts(date)) p[part.type] = part.value;
  const days = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 };
  return {
    date: p.year + '-' + p.month + '-' + p.day,
    weekday: days[p.weekday] || 0,
    weekday_name: p.weekday,
    hour: Number(p.hour) || 0
  };
}
// ---- end log state ------------------------------------------------------------------------
const cfg = $('config').first().json;
const L = cfg.log_columns;
const rows = cleanRows(items.map((i) => i.json || {}), L);

const now = localParts(new Date(), cfg.timezone || 'UTC');
// Monday of this week, as the week's key.
const monday = new Date(Date.parse(now.date + 'T00:00:00Z') - (now.weekday - 1) * 86400000)
  .toISOString().slice(0, 10);
const weekKey = 'report-' + monday;

const sentThisWeek = rows.some((r) => r.status === 'report' && r.slug === weekKey);
const rightTime = now.weekday === cfg.report_weekday && now.hour >= cfg.report_hour;
const due = cfg.using_demo_bank ? true : (rightTime && !sentThisWeek);

const since = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
const week = rows.filter((r) => r.date >= since && r.status !== 'report');
const urns = Array.from(new Set(week.filter((r) => r.status === 'posted' && r.urn).map((r) => r.urn)));

// organizationalEntityShareStatistics takes share URNs and ugcPost URNs in separate List()
// parameters, each URN URL-encoded inside the List — Rest.li 2.0 syntax.
const enc = (u) => encodeURIComponent(u);
const shares = urns.filter((u) => u.startsWith('urn:li:share:'));
const ugc = urns.filter((u) => u.startsWith('urn:li:ugcPost:'));
let statsUrl = 'https://api.linkedin.com/rest/organizationalEntityShareStatistics'
  + '?q=organizationalEntity&organizationalEntity=' + enc(cfg.linkedin_org_urn);
if (shares.length) statsUrl += '&shares=List(' + shares.map(enc).join(',') + ')';
if (ugc.length) statsUrl += '&ugcPosts=List(' + ugc.map(enc).join(',') + ')';

const DAYS = ['', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

return [{
  json: {
    _report_due: due,
    _week: monday,
    _week_key: weekKey,
    _week_rows: week,
    _urns: urns,
    _stats_url: statsUrl,
    _want_stats: cfg.stats_enabled && urns.length > 0,
    _reason: due
      ? (cfg.using_demo_bank ? 'demo log: the weekly report is always due' : 'weekly report due for the week of ' + monday)
      : sentThisWeek
        ? 'the weekly report for the week of ' + monday + ' already went out'
        : 'the weekly report runs ' + DAYS[cfg.report_weekday] + ' from '
          + String(cfg.report_hour).padStart(2, '0') + ':00 (' + cfg.timezone + ')'
  }
}];

// Not time for the weekly report, or it already went out this week.
//
// Fires on almost every poll, and that is the design: one 5-minute trigger drives both the
// approval check and the report, so one `config` node governs both. Two triggers would need
// two config nodes, and two config nodes drift.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: {
    _stopped: 'not the report hour',
    _mode: cfg.mode,
    _reason: '[IDLE] ' + s._reason,
    _at: new Date().toISOString()
  }
}];

// Read LinkedIn's per-post statistics and attach them to the report data.
//
// organizationalEntityShareStatistics returns one element per post, keyed by `share` or
// `ugcPost`, with totalShareStatistics { impressionCount, uniqueImpressionsCount, clickCount,
// likeCount, commentCount, shareCount, engagement }.
//
// A 403 is the common case for apps without Community Management API approval: the endpoint
// needs r_organization_social, which LinkedIn grants by product review, not by scope request.
// That is reported as what it is, and the report still goes out from the log alone.

const due = $('is the weekly report due?').first().json;
const res = $json || {};
const status = Number(res.statusCode || 0);
const body = (res.body && typeof res.body === 'object') ? res.body : {};

const stats = {};
let note = '';
if (status >= 200 && status < 300) {
  for (const el of body.elements || []) {
    const urn = el.share || el.ugcPost || '';
    const t = el.totalShareStatistics || {};
    if (urn) {
      stats[urn] = {
        impressions: t.impressionCount || 0,
        unique: t.uniqueImpressionsCount || 0,
        clicks: t.clickCount || 0,
        likes: t.likeCount || 0,
        comments: t.commentCount || 0,
        shares: t.shareCount || 0,
        engagement: t.engagement || 0
      };
    }
  }
  note = 'statistics for ' + Object.keys(stats).length + ' of ' + due._urns.length + ' post(s)';
} else if (status === 403) {
  note = 'no statistics: LinkedIn returned 403. This endpoint needs r_organization_social, '
    + 'which requires Community Management API approval for the app. Set STATS_ENABLED = false '
    + 'to stop asking.';
} else if (status === 401) {
  note = 'no statistics: the LinkedIn token was rejected (401) — it has probably expired';
} else {
  note = 'no statistics: HTTP ' + status + (body.message ? ' — ' + body.message : '');
}

return [{ json: Object.assign({}, due, { _stats: stats, _stats_note: note, _stats_status: status }) }];

// The week, from the log: what went out, what did not, and what the gates cost.
//
// A pipeline with an approval gate fails quietly in a specific way: drafts start expiring
// unanswered, or edits keep getting refused, and the page simply posts less. None of that is an
// error, so nothing alerts. This report is where it shows up — as counts, once a week, next to
// what did go out and (if STATS_ENABLED) how it did.
//
// Approval time is measured from the FIRST `awaiting` row for a slug to its `posted` row, so a
// draft that was edited twice is counted honestly rather than from its last revision.

const cfg = $('config').first().json;
const d = $json;
const rows = d._week_rows || [];
const stats = d._stats || {};

const count = (s) => rows.filter((r) => r.status === s).length;
const posted = rows.filter((r) => r.status === 'posted');

const hours = [];
for (const p of posted) {
  const first = rows.filter((r) => r.slug === p.slug && r.status === 'awaiting')
    .map((r) => Date.parse(r.at)).filter((t) => !isNaN(t)).sort((a, b) => a - b)[0];
  const done = Date.parse(p.at);
  if (first && !isNaN(done) && done >= first) hours.push((done - first) / 3600000);
}
hours.sort((a, b) => a - b);
const median = hours.length ? Math.round(hours[Math.floor((hours.length - 1) / 2)] * 10) / 10 : null;

const lines = [];
lines.push('*LinkedIn weekly report* — week of ' + d._week + (cfg.using_demo_bank ? ' (demo log)' : ''));
lines.push('');
lines.push('*Published:* ' + posted.length
  + (median !== null ? '   *Median time to approval:* ' + median + 'h' : ''));
for (const p of posted) {
  const s = stats[p.urn];
  lines.push('• ' + p.slug + (p.pillar ? ' (' + p.pillar + ')' : '')
    + (p.urn ? ' — https://www.linkedin.com/feed/update/' + p.urn + '/' : '')
    + (s ? ' — ' + s.impressions + ' impressions, ' + s.clicks + ' clicks, ' + s.likes
      + ' reactions, ' + s.comments + ' comments' : ''));
}
lines.push('');
lines.push('*Not published:* ' + count('cancelled') + ' cancelled, ' + count('expired')
  + ' expired unanswered, ' + count('failed') + ' failed');
lines.push('*Edits:* ' + count('superseded') + ' accepted and re-delivered, ' + count('edit-refused')
  + ' refused by the caption rules');
if (count('alert')) lines.push('*LinkedIn refused the token ' + count('alert') + ' time(s) this week.*');
if (cfg.linkedin_token_days_left !== null && cfg.linkedin_token_days_left <= cfg.token_warn_days) {
  lines.push('*Token:* expires in ' + cfg.linkedin_token_days_left + ' day(s)');
}
if (d._stats_note) lines.push('_' + d._stats_note + '_');
if (count('expired') >= 2) {
  lines.push('');
  lines.push('Two or more drafts expired unanswered. Check that the approvers can see the channel.');
}

const text = lines.join('\n');

return [{
  json: {
    _week: d._week,
    _week_key: d._week_key,
    _report_text: text,
    _report_body: { text: text },
    _published: posted.length,
    _reason: 'weekly report for ' + d._week + ': ' + posted.length + ' published, '
      + count('expired') + ' expired, ' + count('cancelled') + ' cancelled'
  }
}];

// The weekly report was built, but REPORT_WEBHOOK_URL is blank, so it was posted nowhere.
//
// The whole report is in this node's input — open it. Nothing is logged, so it is built again
// on the next poll inside the report hour; with no destination that costs nothing.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: {
    _stopped: 'no report webhook',
    _mode: cfg.mode,
    _report: s._report_text,
    _reason: '[SKIPPED] weekly report built (' + s._week + ') but REPORT_WEBHOOK_URL is blank',
    _at: new Date().toISOString()
  }
}];

// The row that stops the weekly report going out twice.
//
// Written only after the webhook accepted it. `report` rows are ignored by everything that
// reasons about drafts; "is the weekly report due?" looks for this week's key in the Slug.

const cfg = $('config').first().json;
const r = $('build the weekly report').first().json;
const L = cfg.log_columns;

const row = {};
for (const k of Object.keys(L)) row[L[k]] = '';
row[L.date] = new Date().toISOString().slice(0, 10);
row[L.slug] = r._week_key;
row[L.status] = 'report';
row[L.note] = r._reason.slice(0, 900);
row[L.at] = new Date().toISOString();

return [{ json: row }];

// The weekly report was posted, but SHEET_ID is blank, so the `report` row that stops it
// being posted twice this week was not written. Only reachable with a webhook set and no sheet.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: {
    _stopped: 'demo - report not logged',
    _mode: cfg.mode,
    _reason: '[DEMO] the report was posted but there is no Log tab to record it in',
    _would_write: s,
    _at: new Date().toISOString()
  }
}];

// The approval channel, when there is no Discord bot. Demo bank only (SHEET_ID blank).
//
// Messages are returned newest first, exactly as the Discord node's "get many" returns them,
// with the same fields the gate reads: id, author { id, username, bot }, content, attachments,
// edited_timestamp. Alongside the reviewer's reply it holds the two things the gate must
// refuse, so the execution shows them being ignored:
//
//   * another bot saying "post" — a second automation is not a second opinion
//   * a human saying "looks good" — chatter is not a decision
//
// The reply itself is DEMO_REPLY in config: post | cancel | edit | bad-edit.

// ---- demo content (shared) ----------------------------------------------------------------
// Inlined by build.mjs into the demo-only nodes, so workflow 01's demo writer and workflow 02's
// demo channel tell one story: 01 drafts DEMO_DRAFT_CAPTION, 02 finds it open in the log and
// reads a reply to it. None of it is reachable while SHEET_ID is set.

const DEMO_DRAFT = {
  slug: 'demo-never-approve-your-own-work',
  slot: 2,
  pillar: 'Production AI guardrails',
  message_id: '1300000000000000100',
  bot_id: '1100000000000000001'
};

const DEMO_DRAFT_CAPTION = [
  'A workflow that approves its own drafts has no approval step at all.',
  '',
  'It drafts a post, reads its own draft back, and calls that a review. Nothing about the outcome depends on a person, so the delay is the only thing it added.',
  '',
  'The approval that counts is a human, in a channel made for nothing else, typing a word that cannot be mistaken for chat. Four things never count as a yes: the workflow\'s own message, another bot, silence, and a thumbs-up reaction.',
  '',
  'The cost is a few minutes of somebody\'s morning, every morning, and on busy days the post goes out later than planned. We think that is the right price for a company page.',
  '',
  'Who approves what goes out on your page today?',
  '',
  '(Demo draft, not for publication.)',
  '',
  '#Automation #Guardrails #Approval #Workflow #Demo'
].join('\n');

// A reviewer's clean revision: new opening, same argument, still inside every rule.
const DEMO_EDIT_CAPTION = [
  'If the system that writes the post can also approve it, nobody approved it.',
  '',
  'A draft that is posted for review and then read back by the same workflow has not been reviewed. It has been delayed. The outcome never depended on a person.',
  '',
  'So the only yes that counts here is a human, in a channel made for nothing else, typing one word that cannot be mistaken for chat. The workflow\'s own message does not count. Another bot does not count. Silence and a thumbs-up do not count either.',
  '',
  'The cost is a few minutes of somebody\'s morning, and on a busy day the post goes out later than planned. For a company page we think that is cheap.',
  '',
  'Who signs off what goes out on your page?',
  '',
  '(Demo draft, not for publication.)',
  '',
  '#Automation #Guardrails #Approval #Workflow #Demo'
].join('\n');

// An edit the rules refuse: too short, a link in the body, and hashtags mid-caption.
const DEMO_BAD_EDIT_CAPTION = [
  'Shorter version #Approval — the full write-up is at https://example.com/approvals',
  '',
  'Only a human in the right channel can approve a post.',
  '',
  '#Automation #Demo'
].join('\n');
// ---- end demo content ---------------------------------------------------------------------
const cfg = $('config').first().json;

const BOT = { id: DEMO_DRAFT.bot_id, username: 'approvals-bot', bot: true };
const OTHER_BOT = { id: '1100000000000000002', username: 'some-other-bot', bot: true };
const REVIEWER = { id: '1200000000000000001', username: 'reviewer', global_name: 'Demo Reviewer', bot: false };

const reply = {
  post: 'post',
  cancel: 'cancel',
  edit: 'edit\n' + DEMO_EDIT_CAPTION,
  'bad-edit': 'edit\n' + DEMO_BAD_EDIT_CAPTION
}[cfg.demo_reply] || 'post';

const at = (min) => new Date(Date.now() - min * 60000).toISOString();

const messages = [
  { id: '1300000000000000103', author: REVIEWER, content: reply, timestamp: at(5), attachments: [] },
  { id: '1300000000000000102', author: REVIEWER, content: 'looks good, one sec', timestamp: at(20), attachments: [] },
  { id: '1300000000000000101', author: OTHER_BOT, content: 'post', timestamp: at(40), attachments: [] },
  {
    id: DEMO_DRAFT.message_id, author: BOT, timestamp: at(50), edited_timestamp: null,
    content: DEMO_DRAFT_CAPTION + '\n\n' + cfg.approval_instruction,
    attachments: [{
      id: '1400000000000000001', filename: '2026-01-01_' + DEMO_DRAFT.slug + '.png',
      content_type: 'image/png', size: 91234,
      url: 'https://cdn.discordapp.com/attachments/demo/' + DEMO_DRAFT.slug + '.png'
    }]
  },
  { id: '1299999999999999990', author: REVIEWER, content: 'post', timestamp: at(300), attachments: [] }
];

return messages.map((json) => ({ json }));

// Read the channel and decide what a human said about the draft.
//
// This is the gate. Everything downstream of `post` is irreversible, so the rules are narrow and
// every one of them is a refusal:
//
//   * Only messages AFTER the draft count. Anything already in the channel cannot be a reply.
//   * The workflow's own messages never count. Checked against the draft's own author id, not
//     a configured bot id — there is nothing to get wrong.
//   * Other bots never count. A second automation is not a second opinion.
//   * `post` / `cancel` must be the WHOLE message. "post please" and "do not post" are not
//     decisions. Substring matching would make "do not post" an approval.
//   * An EDIT is a message whose first line is exactly an edit word and whose remaining lines
//     are the new caption. It never publishes anything: "check the edited caption" runs the
//     caption rules on it and, if it passes, it goes out again as a NEW draft needing its own
//     `post`. An edit word with nothing under it is not a decision.
//   * Messages this workflow has already acted on (a refused edit) are skipped, by the Reply id
//     the log recorded, so a refusal is answered once rather than every five minutes — and a
//     later `post` can still approve the original.
//   * The FIRST decisive message wins. A cancel is not reopened by a later approval.
//
// Input: messages from the channel, newest first as Discord returns them (or the demo channel).
// Output: exactly one item, always, with _decision = post | edit | cancel | wait, and the draft
// message itself as _draft_message for the nodes after the Switch.

const cfg = $('config').first().json;
const pending = $('find the pending draft').first().json;

const messages = items.map((i) => i.json).filter((m) => m && m.id);

// Discord snowflakes are wider than a JS integer and sort chronologically as numbers — compare
// as BigInt, because string comparison puts a 19-digit id before a 20-digit one.
const anchor = BigInt(pending._message_id);
const draft = messages.find((m) => m.id === pending._message_id);

if (!draft) {
  return [{
    json: Object.assign({}, pending, {
      _decision: 'wait',
      _reason: 'the draft message ' + pending._message_id + ' was not in the messages read back '
        + 'from the channel. It may have scrolled out of the fetch window or been deleted. '
        + 'Nothing is published on an unverifiable draft.'
    })
  }];
}

const botAuthorId = String((draft.author && draft.author.id) || '');
const handled = new Set(pending._handled_reply_ids || []);

const after = messages
  .filter((m) => { try { return BigInt(m.id) > anchor; } catch (e) { return false; } })
  .sort((a, b) => (BigInt(a.id) < BigInt(b.id) ? -1 : 1));   // oldest first

let decision = 'wait';
let approver = '';
let approverId = '';
let said = '';
let replyId = '';
let editText = '';
const ignored = [];

for (const m of after) {
  const authorId = String((m.author && m.author.id) || '');
  const isBot = Boolean(m.author && m.author.bot);
  const original = String(m.content || '').trim();
  const content = original.toLowerCase();

  if (!content) continue;
  if (handled.has(m.id)) { ignored.push('already acted on: ' + m.id); continue; }
  if (authorId === botAuthorId) { ignored.push('own message: "' + content.slice(0, 40) + '"'); continue; }
  if (isBot) {
    ignored.push('another bot (' + ((m.author && m.author.username) || authorId) + '): "'
      + content.slice(0, 40) + '"');
    continue;
  }

  const lines = original.split('\n');
  const firstLine = lines[0].trim().toLowerCase();
  const rest = lines.slice(1).join('\n').trim();

  if (cfg.cancel_words.includes(content)) decision = 'cancel';
  else if (cfg.approve_words.includes(content)) decision = 'post';
  else if (cfg.edit_words.includes(firstLine) && rest) { decision = 'edit'; editText = rest; }
  else {
    ignored.push((cfg.edit_words.includes(firstLine) ? 'an edit with no caption under it: "'
      : 'not a decision: "') + content.slice(0, 40) + '"');
    continue;
  }

  approver = (m.author && (m.author.global_name || m.author.username)) || authorId;
  approverId = authorId;
  said = decision === 'edit' ? 'edit (' + editText.length + ' characters)' : content;
  replyId = m.id;
  break;   // first decisive message wins
}

return [{
  json: Object.assign({}, pending, {
    _decision: decision,
    _approver: approver,
    _approver_id: approverId,
    _said: said,
    _reply_id: replyId,
    _edit_text: editText,
    _draft_message: {
      id: draft.id,
      content: draft.content,
      edited_timestamp: draft.edited_timestamp || null,
      author: draft.author,
      attachments: draft.attachments || []
    },
    _messages_after: after.length,
    _ignored: ignored,
    _reason: decision === 'post' ? approver + ' approved it ("' + said + '")'
      : decision === 'cancel' ? approver + ' cancelled it ("' + said + '")'
      : decision === 'edit' ? approver + ' sent an edit (' + editText.length + ' characters)'
      : 'no decision yet — ' + after.length + ' message(s) since the draft, ' + ignored.length
        + ' ignored'
  })
}];

// The row that closes a draft.
//
// One row per outcome, appended — the log is never rewritten in place. Each one carries the
// draft's message id, which is what closes it (see "find the pending draft"):
//
//   posted     on the page; silences the rest of the day; its Pillar and Hook feed topic
//              rotation and the repeated-hook check from now on
//   cancelled  a reviewer said no; workflow 01 drafts again the same day
//   expired    nobody answered in time; closed without claiming it went out
//
// The bank row's State is updated separately, and only on a real publish. A cancelled post
// stays `ready` on purpose: cancelling means "not this one, now", not "never".

const cfg = $('config').first().json;
const L = cfg.log_columns;
// On the publish path this node runs after "[cred] Sheets - mark the bank row", whose output is
// the bank row it wrote ({ Slug, State }), not the publish result. Read the publish result by
// name there; the cancel and expiry paths hand their own item straight in.
const fromSheet = $json && $json._outcome === undefined && $json._decision === undefined
  && $json._expired === undefined;
const d = fromSheet ? $('read the publish result').first().json : $json;

const status = d._outcome === 'POSTED' ? 'posted'
  : d._outcome === 'DUPLICATE' ? 'posted'
  : d._decision === 'cancel' ? 'cancelled'
  : d._expired ? 'expired'
  : 'failed';

const row = {};
row[L.date] = d._date || '';
row[L.slug] = d._slug || '';
row[L.slot] = d._slot || '';
row[L.status] = status;
row[L.channel_id] = d._channel_id || cfg.channel_id;
row[L.message_id] = d._message_id || '';
row[L.reply_id] = d._reply_id || '';
row[L.caption_fp] = d._caption_fp_now || d._caption_fp || '';
row[L.pillar] = d._pillar || '';
row[L.hook] = status === 'posted' ? (d._hook || '') : '';
row[L.urn] = d._urn || '';
row[L.note] = [
  d._approver ? 'by ' + d._approver : '',
  d._said ? '"' + d._said + '"' : '',
  d._reason || ''
].filter(Boolean).join(' — ').slice(0, 900);
row[L.at] = new Date().toISOString();

return [{ json: Object.assign(row, {
  _status: status, _slug: d._slug, _outcome: d._outcome, _post_url: d._post_url,
  _approver: d._approver, _reason: d._reason
}) }];

// The draft is still open. Nobody has replied yet.
//
// Deliberately does nothing else — no reminder, no nudge, no escalation. A reviewer who has
// not answered has not answered; pinging them from a workflow that publishes on the word
// "post" trains people to type it quickly.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: Object.assign({}, s, {
    _stopped: 'still awaiting approval',
    _mode: cfg.mode,
    _reason: '[WAITING] ' + s._reason,
    _at: new Date().toISOString()
  })
}];

// A reviewer replied `edit` with a new caption. Hold it to exactly the rules a model caption
// meets — length, hashtags, banned phrases, links, @mentions, a repeated hook — and build what
// happens next either way.
//
// Passes  -> it goes back out as a NEW draft: the edited caption, the same image (the
//            attachment on the original draft, fetched by "download the draft image"), and the
//            approval line. The old draft is closed as `superseded`. The edit itself publishes
//            nothing: the reviewer approves the revised draft like any other, with `post`.
// Fails   -> the bot replies to the edit with the reasons, the refusal is logged with the
//            edit's Reply id so it is answered once, and the ORIGINAL draft stays open.
//
// Why re-deliver rather than publish the edit directly: the person approving should be looking
// at the exact message that will be published, fingerprinted, next to its picture — the same
// guarantee every other draft gets.

// ---- caption rules (shared) ---------------------------------------------------------------
// Inlined by build.mjs into every node that judges a caption: "apply the caption", "check the
// rewrite" (workflow 01) and "check the edited caption" (workflow 02). One copy of the rules,
// so a caption the model wrote, a caption the model rewrote and a caption a human typed into
// Discord are held to exactly the same standard.

// FNV-1a. Not a security hash — it lets workflow 02 prove that the caption it is about to
// publish is the one that was approved. require('crypto') needs NODE_FUNCTION_ALLOW_BUILTIN on
// the host, which is the kind of host setting the config rule exists to avoid depending on.
function fingerprint(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return ('0000000' + h.toString(16)).slice(-8);
}

// LinkedIn "little text" reserved characters. '#' is deliberately NOT escaped so hashtags keep
// working; everything else in the reserved set gets a backslash at publish time.
function escapeLittleText(s) {
  const RESERVED = '\\|{}@[]()<>*_~';
  return String(s).split('').map((c) => (RESERVED.includes(c) ? '\\' + c : c)).join('');
}

// A model sometimes wraps its answer in a code fence or in quotes despite being told not to.
// Unwrapping is lossless; anything beyond that would be editing, which no node here does.
function unwrapCaption(s) {
  return String(s || '')
    .replace(/^\s*```[a-z]*\s*\n?/i, '')
    .replace(/\n?```\s*$/i, '')
    .replace(/^\s*["“]([\s\S]+)["”]\s*$/, '$1')
    .trim();
