  refusal = refusal.slice(0, cfg.discord_message_limit - 3) + '...';
}

return [{
  json: Object.assign({}, d, {
    _edit_ok: problems.length === 0,
    _problems: problems,
    _caption: c.caption,
    _caption_fp: c.fp,
    _caption_words: c.words,
    _hook: c.hook,
    _message: message,
    _refusal_message: refusal,
