// image, as a new draft that needs its own `post`. Open this node's input to see the exact
// message that would have been sent.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: {
    _stopped: 'preview - revision not delivered',
    _mode: cfg.mode,
    _slug: s._slug,
