// nothing. So it is where token problems are detected, before anything irreversible:
//
//   ok          an uploadUrl and an image URN came back -> carry on
//   token       401, or EXPIRED_ACCESS_TOKEN / REVOKED_ACCESS_TOKEN / INVALID_ACCESS_TOKEN.
//               LinkedIn tokens last 60 days and lapse with no warning. This is the failure
//               that used to end as a red execution nobody looked at, with an approved post
//               silently not going out.
//   permission  403 — the token is valid but lacks w_organization_social for this page
//   version     426 — LINKEDIN_VERSION has been retired
//   failed      anything else
//
// Anything but `ok` goes to "build the LinkedIn alert", which tells the approval channel once,
// and leaves the approval OPEN: refresh the token and the next poll publishes the same approved
// draft, without anyone approving it twice.
//
// The HTTP node runs with fullResponse + neverError so a 401 arrives here as data instead of
// killing the run inside the node.

const res = $json || {};
const body = (res.body && typeof res.body === 'object') ? res.body : (res.value ? res : {});
const status = Number(res.statusCode || (res.value ? 200 : 0));
const value = body.value || {};

const code = String(body.code || body.serviceErrorCode || body.error || '');
const message = String(body.message || body.error_description || '');

let kind;
if (status >= 200 && status < 300 && value.uploadUrl && value.image) kind = 'ok';
else if (status === 401 || /EXPIRED_ACCESS_TOKEN|REVOKED_ACCESS_TOKEN|INVALID_ACCESS_TOKEN|65600|65601|65602/.test(code + ' ' + message)) kind = 'token';
else if (status === 403) kind = 'permission';
else if (status === 426) kind = 'version';
else kind = 'failed';

const WHY = {
  ok: 'upload registered',
  token: 'LinkedIn rejected the access token (HTTP ' + status + (code ? ', ' + code : '') + '). '
    + 'It has expired or been revoked. Generate a new one, put it in LINKEDIN_ACCESS_TOKEN (and '
    + 'its expiry in LINKEDIN_TOKEN_EXPIRES_ON). The approval stays open; the next poll publishes it.',
  permission: 'LinkedIn refused the request (HTTP 403' + (message ? ': ' + message : '') + '). The '
    + 'token is valid but cannot post as ' + 'this organisation: it needs w_organization_social and '
    + 'an admin role on the page.',
  version: 'HTTP 426: LinkedIn-Version is retired. Raise LINKEDIN_VERSION in config.',
  failed: 'registering the upload failed (HTTP ' + status + (message ? ': ' + message : '') + ').'
};

return [{
  json: {
    _registered: kind === 'ok',
    _kind: kind,
    _token_problem: kind !== 'ok',
    _status: status,
    _upload_url: value.uploadUrl || '',
    _image_urn: value.image || '',
    _reason: WHY[kind]
  }
}];

// Read what LinkedIn said, and decide whether anything is now on the page.
//
// This runs after the irreversible step. The one rule that matters: an UNKNOWN outcome is
// never retried. A publish that timed out may well have succeeded, and a retry puts the same
// post up twice — which cannot be undone from here and looks worse than a missing post.
//
// The three outcomes:
//
//   POSTED     a share URN came back. Log it, notify, done.
//   DUPLICATE  LinkedIn rejected it as already posted. Stop. Not an error to fix.
//   FAILED     a 4xx with a reason. Stop, read the reason, fix the cause. A 4xx does not
//              become a 2xx by being sent again.
//   UNKNOWN    no status, no urn, no error. Check the page by eye before doing anything.

const draft = $('the approved draft').first().json;

const res = $json || {};
const headers = res.headers || {};
const body = res.body !== undefined ? res.body : res;
const status = Number(res.statusCode || res.status || 0);

// The share URN comes back in a header, not the body. n8n lowercases header names on some
// versions and not others.
const urn = String(
  headers['x-restli-id'] || headers['X-RestLi-Id'] || headers['x-linkedin-id']
  || (body && body.id) || ''
);

let outcome;
let reason;

if (urn) {
  outcome = 'POSTED';
  reason = 'published as ' + urn;
} else if (status === 409 || /duplicate/i.test(JSON.stringify(body || ''))) {
  outcome = 'DUPLICATE';
  reason = 'LinkedIn rejected this as a duplicate — it is already on the page. Not retried.';
} else if (status >= 400) {
  const msg = (body && (body.message || body.error_description || body.error)) || '';
  outcome = 'FAILED';
  reason = 'HTTP ' + status + (msg ? ': ' + JSON.stringify(msg) : '')
    + '. Not retried — a 4xx does not fix itself. '
    + (status === 401 || status === 403
        ? 'That status is almost always the token: expired, or missing w_organization_social.'
        : status === 426
          ? 'HTTP 426 is a retired LinkedIn-Version. Raise LINKEDIN_VERSION in config.'
          : '');
} else {
  outcome = 'UNKNOWN';
  reason = 'no URN and no error came back (HTTP ' + status + '). The post may or may not '
    + 'have gone up. LOOK AT THE PAGE before running this again — this is the one case '
    + 'where a retry can double-post.';
}

return [{
  json: Object.assign({}, draft, {
    _outcome: outcome,
    _urn: urn,
    _status: status,
    _posted: outcome === 'POSTED',
    _reason: reason,
    _post_url: urn ? 'https://www.linkedin.com/feed/update/' + urn + '/' : ''
  })
}];

// The publish did not succeed, and it is not being retried.
//
// FAILED means a 4xx with a reason — read it, fix the cause, run again.
// DUPLICATE means it is already on the page. Stop.
// UNKNOWN means look at the page with your own eyes before doing anything at all, because
// this is the one state where running again can double-post.
//
// There is no automatic retry anywhere in this branch, on purpose.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: Object.assign({}, s, {
    _stopped: 'publish failed',
    _mode: cfg.mode,
    _reason: '[' + s._outcome + '] ' + s._reason,
    _at: new Date().toISOString()
  })
}];

// LinkedIn said no before anything was published. Tell the people who approved it — once.
//
// The alert goes to the approval channel because that is where the approver is waiting to see
// the post go out. It repeats only after ALERT_REPEAT_HOURS: the poll runs every five minutes,
// and an alert every five minutes is an alert people mute. When the last one went out is read
// from the log (`alert` rows for this draft's message id), so the dedupe survives restarts.
//
// The bot's own alert message can never approve anything — the gate ignores the bot's messages.

const cfg = $('config').first().json;
const draft = $('the approved draft').first().json;
const reg = $json;

const last = Date.parse(draft._last_alert_at || '');
const hoursSince = isNaN(last) ? Infinity : (Date.now() - last) / 3600000;
const due = hoursSince >= cfg.alert_repeat_hours;

const text = [
  ':rotating_light: **Approved, but not published.**',
  'The draft above was approved by ' + (draft._approver || 'a reviewer') + ', but LinkedIn '
    + 'refused the request: ' + reg._reason,
  '',
  'Nothing was posted. No need to approve again — once this is fixed, it publishes on the next '
    + 'check. It still expires ' + cfg.approval_expires_hours + 'h after it was delivered.'
].join('\n').slice(0, cfg.discord_message_limit);

return [{
  json: Object.assign({}, draft, {
    _kind: reg._kind,
    _token_problem: true,
    _alert_text: text,
    _alert_due: due,
    _hours_since_alert: isFinite(hoursSince) ? Math.round(hoursSince * 10) / 10 : null,
    _reason: reg._reason
  })
}];

// Record that the alert went out, without closing the draft.
//
// `alert` is not a closing status. The approval stays open, so a refreshed token publishes it
// on the next poll; this row only exists so the next poll knows not to alert again yet.

const cfg = $('config').first().json;
const a = $('build the LinkedIn alert').first().json;
const L = cfg.log_columns;
const sent = $json || {};

const row = {};
row[L.date] = a._date;
row[L.slug] = a._slug;
row[L.slot] = a._slot;
row[L.status] = 'alert';
row[L.channel_id] = a._channel_id;
row[L.message_id] = a._message_id;
row[L.reply_id] = String(sent.id || '');
row[L.caption_fp] = a._caption_fp_now || '';
row[L.pillar] = a._pillar || '';
row[L.hook] = '';
row[L.urn] = '';
row[L.note] = ('LinkedIn ' + a._kind + ': ' + a._reason).slice(0, 900);
row[L.at] = new Date().toISOString();

return [{ json: Object.assign(row, {
  _status: 'alert', _slug: a._slug, _token_problem: true, _reason: a._reason
}) }];

// LinkedIn is still refusing, and the channel was already told within ALERT_REPEAT_HOURS.
//
// Not silent: the run still ends here with the reason, and the execution list shows it. It just
// does not post the same alert again five minutes after the last one.
const cfg = $('config').first().json;
const s = $json;

return [{
  json: {
    _stopped: 'LinkedIn alert already sent',
    _mode: cfg.mode,
    _slug: s._slug,
    _token_problem: true,
    _reason: '[BLOCKED] ' + s._reason + ' (channel alerted ' + s._hours_since_alert
      + 'h ago; next alert after ' + cfg.alert_repeat_hours + 'h)',
    _at: new Date().toISOString()
  }
}];

// Mark the bank row published so it can never be drafted a second time.
//
// Only ever runs on a real POSTED outcome. The log already prevents a re-draft on its own —
// `_posted_slugs` is read from it — so this is the second of two independent guards, not the
// only one. Two guards because the failure it prevents is publishing the same post twice.

const cfg = $('config').first().json;
const B = cfg.bank_columns;
const d = $json;

const row = {};
row[B.slug] = d._slug;
row[B.state] = 'posted';

return [{ json: Object.assign(row, {
  _reason: 'bank row ' + d._slug + ' marked posted'
}) }];

// The row that closes a draft.
//
// One row per outcome, appended — the log is never rewritten in place. Each one carries the
// draft's message id, which is what closes it (see "find the pending draft"):
//
//   posted     on the page; silences the rest of the day; its Pillar and Hook feed topic
//              rotation and the repeated-hook check from now on
//   cancelled  a reviewer said no; workflow 01 drafts again the same day
//   expired    nobody answered in time; closed without claiming it went out
//
// The bank row's State is updated separately, and only on a real publish. A cancelled post
// stays `ready` on purpose: cancelling means "not this one, now", not "never".

const cfg = $('config').first().json;
const L = cfg.log_columns;
// On the publish path this node runs after "[cred] Sheets - mark the bank row", whose output is
// the bank row it wrote ({ Slug, State }), not the publish result. Read the publish result by
// name there; the cancel and expiry paths hand their own item straight in.
const fromSheet = $json && $json._outcome === undefined && $json._decision === undefined
  && $json._expired === undefined;
const d = fromSheet ? $('read the publish result').first().json : $json;

const status = d._outcome === 'POSTED' ? 'posted'
  : d._outcome === 'DUPLICATE' ? 'posted'
  : d._decision === 'cancel' ? 'cancelled'
  : d._expired ? 'expired'
  : 'failed';

const row = {};
row[L.date] = d._date || '';
row[L.slug] = d._slug || '';
row[L.slot] = d._slot || '';
row[L.status] = status;
row[L.channel_id] = d._channel_id || cfg.channel_id;
row[L.message_id] = d._message_id || '';
row[L.reply_id] = d._reply_id || '';
row[L.caption_fp] = d._caption_fp_now || d._caption_fp || '';
row[L.pillar] = d._pillar || '';
row[L.hook] = status === 'posted' ? (d._hook || '') : '';
row[L.urn] = d._urn || '';
row[L.note] = [
  d._approver ? 'by ' + d._approver : '',
  d._said ? '"' + d._said + '"' : '',
  d._reason || ''
].filter(Boolean).join(' — ').slice(0, 900);
row[L.at] = new Date().toISOString();

return [{ json: Object.assign(row, {
  _status: status, _slug: d._slug, _outcome: d._outcome, _post_url: d._post_url,
  _approver: d._approver, _reason: d._reason
}) }];

// SHEET_ID is blank, so there is no Log tab to append to.
//
// The row that WOULD have been written is the input to this node — open it to see exactly what
// the sheet would have gained. With a sheet configured this branch is never taken.
const cfg = $('config').first().json;
const rows = items.map((i) => i.json);

return [{
  json: {
    _stopped: 'demo - log row not written',
    _mode: cfg.mode,
    _would_write: rows,
    _status: rows.map((r) => r[cfg.log_columns.status]).join(', '),
    _slug: (rows[0] || {})[cfg.log_columns.slug] || '',
    _reason: '[DEMO] SHEET_ID is blank, so ' + rows.length + ' log row(s) were built but not '
      + 'written: ' + rows.map((r) => r[cfg.log_columns.status]).join(', '),
    _at: new Date().toISOString()
  }
}];

// One message per run that is worth a message, for the optional Slack webhook.
//
// Every path through both workflows arrives here, including the ones that did nothing, so a
// job that silently stopped drafting three weeks ago is noticed. But workflow 02 polls every
// five minutes, and almost every poll ends "nothing awaiting" or "still awaiting approval" —
// posting those would bury the one message that matters under 280 that do not. Those are
// QUIET: visible in the execution list, not sent.
//
// The caption is NOT included. It goes to the approval channel and nowhere else — a draft
// that reaches a second audience before it is approved has left the approval gate behind.

const cfg = $('config').first().json;
const s = $json;

const stopped = s._stopped || '';
const outcome = s._outcome || '';
const status = s._status || '';

const QUIET = ['nothing awaiting', 'still awaiting approval', 'LinkedIn alert already sent'];

const icon = outcome === 'POSTED' ? ':white_check_mark:'
  : s._token_problem ? ':rotating_light:'
  : outcome === 'FAILED' || outcome === 'UNKNOWN' || stopped === 'no image' ? ':x:'
  : stopped === 'caption held' || stopped === 'log conflict' ? ':warning:'
  : ':information_source:';

const headline = outcome === 'POSTED'
  ? 'Published: ' + (s._slug || 'unknown')
  : s._token_problem
    ? 'LinkedIn rejected the token — approved draft waiting: ' + (s._slug || 'unknown')
    : stopped
      ? 'No post: ' + stopped
      : status
        ? 'Draft ' + (s._slug || s.Slug || '') + ' ' + status
        : 'Draft delivered for approval: ' + (s.slug || s._slug || 'unknown');

// The early warning for the failure that has actually happened: a 60-day token lapsing on a
// weekend with nothing to say so.
const warnings = (s._warnings || []).slice();
const left = cfg.linkedin_token_days_left;
if (left !== null && left !== undefined && left <= cfg.token_warn_days) {
  warnings.push(left < 0
    ? 'the LinkedIn token expired ' + (-left) + ' day(s) ago (LINKEDIN_TOKEN_EXPIRES_ON). '
      + 'Approved drafts will not publish until it is refreshed.'
    : 'the LinkedIn token expires in ' + left + ' day(s). Refresh it and update '
      + 'LINKEDIN_TOKEN_EXPIRES_ON.');
}

const lines = [
  icon + ' *LinkedIn daily* — ' + headline,
  '*Mode:* ' + cfg.mode + (cfg.forced_preview ? ' (forced — demo bank in use)' : ''),
  s._reason ? '*Why:* ' + s._reason : '',
  s._post_url ? '*Post:* ' + s._post_url : '',
  s._approver ? '*By:* ' + s._approver : '',
  warnings.length ? '*Warnings:* ' + warnings.join('; ') : ''
].filter(Boolean);

const text = lines.join('\n');
// The token warning rides on workflow 01's once-a-day summary; it does not un-quiet a poll.
const quiet = QUIET.includes(stopped);

return [{
  json: {
    _summary: text,
    _slack_body: { text: text },
    _notify: cfg.report_enabled && !quiet,
    _quiet: quiet,
    _outcome: outcome || stopped || status || 'delivered',
    _reason: s._reason || ''
  }
}];
